import{_ as n,c as t,o as i,a3 as r}from"./chunks/framework.CoV49S2T.js";const c=JSON.parse('{"title":"Nutzungsanleitung","description":"","frontmatter":{},"headers":[],"relativePath":"de/guide/usage.md","filePath":"de/guide/usage.md","lastUpdated":1786595765000}'),a={name:"de/guide/usage.md"};function l(s,e,o,u,d,g){return i(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="nutzungsanleitung" tabindex="-1">Nutzungsanleitung <a class="header-anchor" href="#nutzungsanleitung" aria-label="Permalink to &quot;Nutzungsanleitung&quot;">​</a></h1><h2 id="zwischenablagen-verlauf" tabindex="-1">Zwischenablagen-Verlauf <a class="header-anchor" href="#zwischenablagen-verlauf" aria-label="Permalink to &quot;Zwischenablagen-Verlauf&quot;">​</a></h2><p>ClipboardxAI läuft in Ihrer <strong>Menüleiste</strong>. Jedes Mal, wenn Sie etwas kopieren, wird es Ihrem Verlauf hinzugefügt.</p><ul><li>Klicken Sie auf das Menüleisten-Symbol, um das Verlaufs-Panel zu öffnen.</li><li>Fahren Sie mit der Maus über einen Eintrag und drücken Sie den Aktions-Shortcut, oder klicken Sie, um ihn zurück in die Zwischenablage zu kopieren.</li><li>Nutzen Sie das Suchfeld, um einen Eintrag anhand des Texts zu finden.</li></ul><h2 id="das-ki-werkzeug-fenster" tabindex="-1">Das KI-Werkzeug-Fenster <a class="header-anchor" href="#das-ki-werkzeug-fenster" aria-label="Permalink to &quot;Das KI-Werkzeug-Fenster&quot;">​</a></h2><p>Das <strong>KI-Werkzeug</strong>-Fenster ist der Ort, an dem Aktionen ausgeführt werden. Es verwendet ein geteiltes Layout:</p><ul><li><strong>Links</strong> — eine Liste von Werkzeugen, gruppiert in: <ul><li><strong>Built-in AI</strong> — Zusammenfassung, Übersetzung und weitere KI-Aktionen.</li><li><strong>Built-in Local</strong> — Offline-Werkzeuge (extract links, count stats, collapse blank lines).</li><li><strong>Installed</strong> — Aktionen, die Sie aus dem Marketplace hinzugefügt haben. Sie können sie per Drag &amp; Drop <strong>neu anordnen</strong>.</li></ul></li><li><strong>Rechts</strong> — zwei Bereiche: der <strong>originale</strong> Eintrag auf der einen und das <strong>Ergebnis</strong> auf der anderen Seite.</li></ul><p>KI-Werkzeuge zeigen ein „cloud&quot;-Abzeichen; lokale Werkzeuge zeigen ein „device&quot;-Abzeichen, sodass Sie immer wissen, ob eine Aktion das Netzwerk nutzt.</p><h2 id="ausfuhren-einer-aktion" tabindex="-1">Ausführen einer Aktion <a class="header-anchor" href="#ausfuhren-einer-aktion" aria-label="Permalink to &quot;Ausführen einer Aktion&quot;">​</a></h2><ol><li>Wählen Sie ein Werkzeug aus der linken Liste (oder nehmen Sie einen intelligenten Vorschlag an).</li><li>Der aktuelle Eintrag erscheint im Bereich <strong>original</strong>.</li><li>Das Ergebnis wird im Bereich <strong>result</strong> erzeugt.</li></ol><h3 id="auto-run" tabindex="-1">Auto-run <a class="header-anchor" href="#auto-run" aria-label="Permalink to &quot;Auto-run&quot;">​</a></h3><p>Aktivieren Sie <strong>Auto-run on output</strong> in der Fußzeile des Fensters. Wenn aktiviert, läuft das ausgewählte Werkzeug automatisch in dem Moment, in dem Sie etwas kopieren — ohne manuellen Klick. Lokale Werkzeuge überschreiben Ihre Zwischenablage niemals, sodass Auto-run sicher ist.</p><h2 id="eingebaute-lokale-werkzeuge" tabindex="-1">Eingebaute lokale Werkzeuge <a class="header-anchor" href="#eingebaute-lokale-werkzeuge" aria-label="Permalink to &quot;Eingebaute lokale Werkzeuge&quot;">​</a></h2><p>Diese laufen vollständig offline auf Ihrem Mac:</p><ul><li><strong>Extract Links</strong> — gibt jede im Text gefundene URL zurück.</li><li><strong>Count Stats</strong> — Wort-/Zeichen-/Zeilen-/Satzzählung.</li><li><strong>Collapse Blank Lines</strong> — entfernt leere Zeilen aus eingefügtem Text.</li></ul><h2 id="cloud-ki-einrichtung" tabindex="-1">Cloud-KI-Einrichtung <a class="header-anchor" href="#cloud-ki-einrichtung" aria-label="Permalink to &quot;Cloud-KI-Einrichtung&quot;">​</a></h2><p>Um KI-Aktionen zu nutzen, verbinden Sie einen Anbieter unter <strong>Einstellungen → KI</strong>:</p><ol><li>Wählen Sie einen Anbieter — <strong>DeepSeek</strong>, <strong>MiniMax</strong>, <strong>Zhipu GLM</strong>, <strong>Kimi (Moonshot)</strong>, <strong>Mistral</strong>, <strong>Ollama</strong> (lokal) oder einen anderen OpenAI-kompatiblen Dienst.</li><li>Fügen Sie Ihren <strong>API-Schlüssel</strong> ein. Er wird im <strong>Keychain</strong> gespeichert, niemals im Klartext auf die Festplatte geschrieben.</li><li>Wählen Sie ein Modell.</li><li>Cloud-KI ist standardmäßig deaktiviert. Wenn aktiviert, wird Ihr Eintrag nur an den von Ihnen konfigurierten Anbieter gesendet.</li></ol><p>Falls kein Schlüssel festgelegt ist, erinnert Sie das Konfigurations-Banner im KI-Werkzeug-Fenster daran.</p><h2 id="marketplace" tabindex="-1">Marketplace <a class="header-anchor" href="#marketplace" aria-label="Permalink to &quot;Marketplace&quot;">​</a></h2><ol><li>Öffnen Sie den <strong>Marketplace</strong> aus dem KI-Werkzeug-Fenster (oder der <a href="/de/marketplace/">Marketplace</a>-Seite der Website).</li><li>Klicken Sie bei einer Aktion auf <strong>Install</strong>. Dadurch wird die App über den Deep-Link <code>clipboardxai://install?action=&lt;id&gt;</code> geöffnet und die Aktion Ihrer Liste <strong>Installed</strong> hinzugefügt.</li></ol><h2 id="tastenkurzel" tabindex="-1">Tastenkürzel <a class="header-anchor" href="#tastenkurzel" aria-label="Permalink to &quot;Tastenkürzel&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Tastenkürzel</th><th>Aktion</th></tr></thead><tbody><tr><td><code>Cmd+Shift+V</code></td><td>Zwischenablagen-Verlauf öffnen</td></tr><tr><td><code>Cmd+,</code></td><td>Einstellungen öffnen</td></tr><tr><td><code>Cmd+W</code></td><td>Fenster schließen</td></tr><tr><td><code>Cmd+Q</code></td><td>Anwendung beenden</td></tr></tbody></table><blockquote><p>Die genauen Tastenkürzel können je nach Build variieren; prüfen Sie <strong>Einstellungen → Shortcuts</strong> in der App.</p></blockquote><h2 id="einstellungen" tabindex="-1">Einstellungen <a class="header-anchor" href="#einstellungen" aria-label="Permalink to &quot;Einstellungen&quot;">​</a></h2><p>Öffnen Sie <strong>ClipboardxAI → Einstellungen</strong> (oder <code>Cmd+,</code>):</p><ul><li><strong>General</strong>: Sprache, Start beim Anmelden, Erscheinungsbild-Theme.</li><li><strong>AI</strong>: Cloud-Anbieter, Modell und API-Schlüssel (Keychain).</li><li><strong>Actions</strong>: Auto-run-Schalter, ausgeschlossene Apps und Werkzeug-Reihenfolge.</li><li><strong>Privacy</strong>: Cloud-KI-Opt-in, ausgeschlossene Apps und Verlaufssteuerung.</li><li><strong>Marketplace</strong>: Installierte Aktionen durchsuchen und verwalten.</li></ul>',27)])])}const k=n(a,[["render",l]]);export{c as __pageData,k as default};
